class MicroVMError(Exception):
    """Base error for every microvm failure."""


class LexError(MicroVMError):
    """Lexical error. offset is a zero-based character index."""

    def __init__(self, message: str, offset: int) -> None:
        super().__init__(f"{message} at offset {offset}")
        self.offset = offset


class ParseError(MicroVMError):
    """Syntax error. offset is a zero-based character index."""

    def __init__(self, message: str, offset: int) -> None:
        super().__init__(f"{message} at offset {offset}")
        self.offset = offset


class CompileError(MicroVMError):
    """Compile-time semantic error."""


class SerializationError(MicroVMError):
    """Binary codec error."""


class VMRuntimeError(MicroVMError):
    """Error raised while executing bytecode."""


class StepLimitError(VMRuntimeError):
    """Raised when execution would exceed the instruction budget."""

OPCODES: tuple[str, ...] = (
    "CONST", "LOAD", "STORE", "ADD", "SUB", "MUL", "DIV", "MOD", "NEG", "NOT",
    "EQ", "NE", "LT", "LE", "GT", "GE", "JUMP", "JUMP_IF_FALSE", "PRINT", "POP", "HALT",
)
OPCODE_NUMBERS: dict[str, int] = {name: index + 1 for index, name in enumerate(OPCODES)}

import dataclasses

from microvm.errors import LexError

_KEYWORDS = frozenset({
    "let", "print", "if", "else", "while", "true", "false", "and", "or", "not",
})
_TWO_CHAR_OPS = frozenset({"==", "!=", "<=", ">="})
_ONE_CHAR_OPS = frozenset("+-*/%(){};=<>")
_ESCAPES = {"n": "\n", "t": "\t", '"': '"', "\\": "\\"}


@dataclasses.dataclass(frozen=True)
class Token:
    kind: str
    text: str
    value: object
    offset: int


def tokenize(src: str) -> list[Token]:
    return _Lexer(src).tokens()


def _is_digit(ch: str) -> bool:
    return len(ch) == 1 and "0" <= ch <= "9"


def _is_ident_start(ch: str) -> bool:
    return ch == "_" or ("A" <= ch <= "Z") or ("a" <= ch <= "z")


def _is_ident_continue(ch: str) -> bool:
    return _is_ident_start(ch) or _is_digit(ch)


class _Lexer:
    def __init__(self, src: str) -> None:
        self.src = src
        self.pos = 0
        self._out: list[Token] = []

    def tokens(self) -> list[Token]:
        while self.pos < len(self.src):
            self._skip()
            if self.pos >= len(self.src):
                break
            self._out.append(self._scan())
        return self._out

    def _skip(self) -> None:
        while self.pos < len(self.src):
            ch = self.src[self.pos]
            if ch in " \t\r\n\f\v":
                self.pos += 1
                continue
            if self.src.startswith("//", self.pos):
                self._skip_comment()
                continue
            return

    def _skip_comment(self) -> None:
        self.pos += 2
        while self.pos < len(self.src) and self.src[self.pos] != "\n":
            self.pos += 1

    def _scan(self) -> Token:
        ch = self.src[self.pos]
        if _is_digit(ch):
            return self._number()
        if ch == '"':
            return self._string()
        if _is_ident_start(ch):
            return self._ident()
        if ch == ".":
            raise LexError("invalid number", self.pos)
        return self._operator()

    def _number(self) -> Token:
        start = self.pos
        self._digits()
        if self._peek() != ".":
            text = self.src[start:self.pos]
            return Token("INT", text, int(text), start)
        return self._float(start)

    def _float(self, start: int) -> Token:
        # `1.` is illegal. Offset points at the dot that makes the lexeme invalid.
        if not _is_digit(self._peek(1)):
            raise LexError("invalid float", self.pos)
        self.pos += 1
        self._digits()
        self._exponent()
        text = self.src[start:self.pos]
        return Token("FLOAT", text, float(text), start)

    def _exponent(self) -> None:
        # `1.5e` without exponent digits is a float plus a later identifier, not an error.
        if self._peek() not in "eE":
            return
        index = self.pos + 1
        if self._at(index) in "+-":
            index += 1
        if not _is_digit(self._at(index)):
            return
        self.pos = index
        self._digits()

    def _string(self) -> Token:
        start = self.pos
        self.pos += 1
        chars: list[str] = []
        while self.pos < len(self.src):
            ch = self.src[self.pos]
            if ch == '"':
                self.pos += 1
                value = "".join(chars)
                return Token("STRING", value, value, start)
            if ch in "\n\r":
                raise LexError("newline in string", self.pos)
            if ch == "\\":
                chars.append(self._escape())
                continue
            chars.append(ch)
            self.pos += 1
        raise LexError("unterminated string", start)

    def _escape(self) -> str:
        slash = self.pos
        self.pos += 1
        if self.pos >= len(self.src):
            raise LexError("unterminated string", slash)
        ch = self.src[self.pos]
        self.pos += 1
        if ch not in _ESCAPES:
            raise LexError("invalid escape", slash)
        return _ESCAPES[ch]

    def _ident(self) -> Token:
        start = self.pos
        self.pos += 1
        while _is_ident_continue(self._peek()):
            self.pos += 1
        text = self.src[start:self.pos]
        if text in _KEYWORDS:
            return Token("KEYWORD", text, text, start)
        return Token("IDENT", text, text, start)

    def _operator(self) -> Token:
        start = self.pos
        two = self.src[start:start + 2]
        if two in _TWO_CHAR_OPS:
            self.pos += 2
            return Token("OP", two, two, start)
        ch = self.src[start]
        if ch in _ONE_CHAR_OPS:
            self.pos += 1
            return Token("OP", ch, ch, start)
        raise LexError("unexpected character", start)

    def _digits(self) -> None:
        while _is_digit(self._peek()):
            self.pos += 1

    def _peek(self, ahead: int = 0) -> str:
        return self._at(self.pos + ahead)

    def _at(self, index: int) -> str:
        if index < 0 or index >= len(self.src):
            return ""
        return self.src[index]

import dataclasses
from typing import NoReturn, cast

from microvm.errors import ParseError
from microvm.lexer import Token, tokenize

_CMP_OPS = frozenset({"==", "!=", "<", "<=", ">", ">="})
_ADD_OPS = frozenset({"+", "-"})
_MUL_OPS = frozenset({"*", "/", "%"})


@dataclasses.dataclass(frozen=True)
class IntLit:
    value: int
    offset: int


@dataclasses.dataclass(frozen=True)
class FloatLit:
    value: float
    offset: int


@dataclasses.dataclass(frozen=True)
class StringLit:
    value: str
    offset: int


@dataclasses.dataclass(frozen=True)
class BoolLit:
    value: bool
    offset: int


@dataclasses.dataclass(frozen=True)
class Ident:
    name: str
    offset: int


@dataclasses.dataclass(frozen=True)
class UnaryOp:
    op: str
    operand: object
    offset: int


@dataclasses.dataclass(frozen=True)
class BinaryOp:
    op: str
    left: object
    right: object
    offset: int


@dataclasses.dataclass(frozen=True)
class LetStmt:
    name: str
    expr: object
    offset: int


@dataclasses.dataclass(frozen=True)
class AssignStmt:
    name: str
    expr: object
    offset: int


@dataclasses.dataclass(frozen=True)
class PrintStmt:
    expr: object
    offset: int


@dataclasses.dataclass(frozen=True)
class IfStmt:
    cond: object
    then_body: object
    else_body: object | None
    offset: int


@dataclasses.dataclass(frozen=True)
class WhileStmt:
    cond: object
    body: object
    offset: int


@dataclasses.dataclass(frozen=True)
class Block:
    statements: list[object]
    offset: int


@dataclasses.dataclass(frozen=True)
class ProgramNode:
    statements: list[object]


def parse(src: str) -> object:
    return _Parser(src, tokenize(src)).parse_program()


class _Parser:
    def __init__(self, src: str, tokens: list[Token]) -> None:
        self.src = src
        self.tokens = tokens
        self.pos = 0

    def parse_program(self) -> ProgramNode:
        statements: list[object] = []
        while not self._at_end():
            statements.append(self._statement())
        return ProgramNode(statements)

    def _statement(self) -> object:
        if self._check_keyword("let"):
            return self._let()
        if self._check_keyword("print"):
            return self._print()
        if self._check_keyword("if"):
            return self._if()
        if self._check_keyword("while"):
            return self._while()
        if self._check_op("{"):
            return self._block()
        if self._check_kind("IDENT"):
            return self._assign()
        self._fail("unexpected token")

    def _let(self) -> LetStmt:
        keyword = self._advance()
        name = self._expect_ident()
        self._expect_op("=")
        expr = self._expr()
        self._expect_op(";")
        return LetStmt(name.text, expr, keyword.offset)

    def _assign(self) -> AssignStmt:
        name = self._advance()
        self._expect_op("=")
        expr = self._expr()
        self._expect_op(";")
        return AssignStmt(name.text, expr, name.offset)

    def _print(self) -> PrintStmt:
        keyword = self._advance()
        expr = self._expr()
        self._expect_op(";")
        return PrintStmt(expr, keyword.offset)

    def _if(self) -> IfStmt:
        keyword = self._advance()
        self._expect_op("(")
        cond = self._expr()
        self._expect_op(")")
        then_body = self._block()
        else_body: object | None = None
        if self._match_keyword("else"):
            else_body = self._if() if self._check_keyword("if") else self._block()
        return IfStmt(cond, then_body, else_body, keyword.offset)

    def _while(self) -> WhileStmt:
        keyword = self._advance()
        self._expect_op("(")
        cond = self._expr()
        self._expect_op(")")
        return WhileStmt(cond, self._block(), keyword.offset)

    def _block(self) -> Block:
        brace = self._expect_op("{")
        statements: list[object] = []
        while not self._at_end() and not self._check_op("}"):
            statements.append(self._statement())
        self._expect_op("}")
        return Block(statements, brace.offset)

    def _expr(self) -> object:
        return self._or()

    def _or(self) -> object:
        left = self._and()
        while self._check_keyword("or"):
            op = self._advance()
            left = BinaryOp("or", left, self._and(), op.offset)
        return left

    def _and(self) -> object:
        left = self._not()
        while self._check_keyword("and"):
            op = self._advance()
            left = BinaryOp("and", left, self._not(), op.offset)
        return left

    def _not(self) -> object:
        # Grammar binds `not` outside comparison: `not a == b` is `not (a == b)`.
        if not self._check_keyword("not"):
            return self._comparison()
        op = self._advance()
        return UnaryOp("not", self._not(), op.offset)

    def _comparison(self) -> object:
        left = self._additive()
        if not self._check_op_set(_CMP_OPS):
            return left
        op = self._advance()
        right = self._additive()
        if self._check_op_set(_CMP_OPS):
            self._fail("comparison is not associative")
        return BinaryOp(op.text, left, right, op.offset)

    def _additive(self) -> object:
        left = self._multiplicative()
        while self._check_op_set(_ADD_OPS):
            op = self._advance()
            left = BinaryOp(op.text, left, self._multiplicative(), op.offset)
        return left

    def _multiplicative(self) -> object:
        left = self._unary()
        while self._check_op_set(_MUL_OPS):
            op = self._advance()
            left = BinaryOp(op.text, left, self._unary(), op.offset)
        return left

    def _unary(self) -> object:
        if not self._check_op("-"):
            return self._primary()
        op = self._advance()
        return UnaryOp("-", self._unary(), op.offset)

    def _primary(self) -> object:
        if self._at_end():
            self._fail("unexpected end of input")
        tok = self._peek()
        if tok.kind == "INT":
            self._advance()
            return IntLit(cast(int, tok.value), tok.offset)
        if tok.kind == "FLOAT":
            self._advance()
            return FloatLit(cast(float, tok.value), tok.offset)
        if tok.kind == "STRING":
            self._advance()
            return StringLit(cast(str, tok.value), tok.offset)
        if tok.kind == "KEYWORD" and tok.text in ("true", "false"):
            self._advance()
            return BoolLit(tok.text == "true", tok.offset)
        if tok.kind == "IDENT":
            self._advance()
            return Ident(tok.text, tok.offset)
        if tok.kind == "OP" and tok.text == "(":
            self._advance()
            expr = self._expr()
            self._expect_op(")")
            return expr
        self._fail("unexpected token")

    def _at_end(self) -> bool:
        return self.pos >= len(self.tokens)

    def _peek(self) -> Token:
        if self._at_end():
            raise ParseError("unexpected end of input", len(self.src))
        return self.tokens[self.pos]

    def _advance(self) -> Token:
        tok = self._peek()
        self.pos += 1
        return tok

    def _check_kind(self, kind: str) -> bool:
        return not self._at_end() and self.tokens[self.pos].kind == kind

    def _check_keyword(self, text: str) -> bool:
        if self._at_end():
            return False
        tok = self.tokens[self.pos]
        return tok.kind == "KEYWORD" and tok.text == text

    def _check_op(self, text: str) -> bool:
        if self._at_end():
            return False
        tok = self.tokens[self.pos]
        return tok.kind == "OP" and tok.text == text

    def _check_op_set(self, ops: frozenset[str]) -> bool:
        if self._at_end():
            return False
        tok = self.tokens[self.pos]
        return tok.kind == "OP" and tok.text in ops

    def _match_keyword(self, text: str) -> bool:
        if not self._check_keyword(text):
            return False
        self.pos += 1
        return True

    def _expect_op(self, text: str) -> Token:
        if not self._check_op(text):
            self._fail(f"expected '{text}'")
        return self._advance()

    def _expect_ident(self) -> Token:
        if not self._check_kind("IDENT"):
            self._fail("expected identifier")
        return self._advance()

    def _fail(self, message: str) -> NoReturn:
        raise ParseError(message, self._error_offset())

    def _error_offset(self) -> int:
        if self._at_end():
            return len(self.src)
        return self.tokens[self.pos].offset

from microvm.compiler import Instr, Program


def disassemble(program: Program) -> str:
    lines = [
        _format_line(index, instr, program)
        for index, instr in enumerate(program.instructions)
    ]
    return "".join(f"{line}\n" for line in lines)


def _format_line(index: int, instr: Instr, program: Program) -> str:
    if instr.arg is None:
        return f"{index:04d} {instr.op}"
    text = f"{index:04d} {instr.op} {instr.arg}"
    if instr.op != "CONST":
        return text
    return f"{text}  ; {_render_constant(program.constants[instr.arg])}"


def _render_constant(value: object) -> str:
    if type(value) is bool:
        return "true" if value else "false"
    if type(value) is str:
        return '"' + _escape(value) + '"'
    return str(value)


def _escape(text: str) -> str:
    return (
        text.replace("\\", "\\\\")
        .replace('"', '\\"')
        .replace("\n", "\\n")
        .replace("\t", "\\t")
    )

import dataclasses
import struct
from typing import cast

from microvm.optimizer import fold_constants
from microvm.parser import (
    AssignStmt,
    BinaryOp,
    Block,
    BoolLit,
    FloatLit,
    Ident,
    IfStmt,
    IntLit,
    LetStmt,
    PrintStmt,
    ProgramNode,
    StringLit,
    UnaryOp,
    WhileStmt,
    parse,
)
from microvm.errors import CompileError

_LITERALS = (IntLit, FloatLit, StringLit, BoolLit)
_BIN_OPS = {
    "+": "ADD",
    "-": "SUB",
    "*": "MUL",
    "/": "DIV",
    "%": "MOD",
    "==": "EQ",
    "!=": "NE",
    "<": "LT",
    "<=": "LE",
    ">": "GT",
    ">=": "GE",
}


@dataclasses.dataclass(frozen=True)
class Instr:
    op: str
    arg: int | None


@dataclasses.dataclass
class Program:
    constants: list[object]
    names: list[str]
    instructions: list[Instr]


def compile_source(src: str, *, optimize: bool = False) -> Program:
    tree = parse(src)
    if optimize:
        tree = fold_constants(tree)
    return _emit_program(tree)


def _emit_program(tree: object) -> Program:
    root = cast(ProgramNode, tree)
    names = _declare(root)
    compiler = _Compiler(names)
    for stmt in root.statements:
        compiler.statement(stmt)
    compiler.emit("HALT")
    return Program(compiler.constants, names, compiler.instructions)


def _declare(node: object) -> list[str]:
    found: list[str] = []
    _walk_decls(node, found, set())
    return found


def _walk_decls(node: object, found: list[str], seen: set[str]) -> None:
    if type(node) is LetStmt:
        let = cast(LetStmt, node)
        if let.name in seen:
            raise CompileError(f"duplicate declaration: {let.name}")
        seen.add(let.name)
        found.append(let.name)
    for child in _children(node):
        _walk_decls(child, found, seen)


def _children(node: object) -> list[object]:
    kind = type(node)
    if kind is ProgramNode:
        return list(cast(ProgramNode, node).statements)
    if kind is Block:
        return list(cast(Block, node).statements)
    if kind is LetStmt:
        return [cast(LetStmt, node).expr]
    if kind is AssignStmt:
        return [cast(AssignStmt, node).expr]
    if kind is PrintStmt:
        return [cast(PrintStmt, node).expr]
    if kind is IfStmt:
        return _if_children(cast(IfStmt, node))
    if kind is WhileStmt:
        stmt = cast(WhileStmt, node)
        return [stmt.cond, stmt.body]
    if kind is BinaryOp:
        expr = cast(BinaryOp, node)
        return [expr.left, expr.right]
    if kind is UnaryOp:
        return [cast(UnaryOp, node).operand]
    return []


def _if_children(stmt: IfStmt) -> list[object]:
    children = [stmt.cond, stmt.then_body]
    if stmt.else_body is not None:
        children.append(stmt.else_body)
    return children


def _pool_key(value: object) -> object:
    # -0.0 and 0.0 compare equal but str() differs; keep both pool entries.
    if type(value) is float:
        return ("float", struct.pack(">d", value))
    return (type(value), value)


class _Compiler:
    def __init__(self, names: list[str]) -> None:
        self.constants: list[object] = []
        self.instructions: list[Instr] = []
        self._keys: dict[object, int] = {}
        self._names = {name: index for index, name in enumerate(names)}

    def emit(self, op: str, arg: int | None = None) -> int:
        self.instructions.append(Instr(op, arg))
        return len(self.instructions) - 1

    def patch(self, index: int, arg: int) -> None:
        self.instructions[index] = Instr(self.instructions[index].op, arg)

    def pool(self, value: object) -> int:
        key = _pool_key(value)
        found = self._keys.get(key)
        if found is not None:
            return found
        index = len(self.constants)
        self.constants.append(value)
        self._keys[key] = index
        return index

    def statement(self, node: object) -> None:
        kind = type(node)
        if kind is Block:
            self._block(cast(Block, node))
            return
        if kind is LetStmt:
            self._let(cast(LetStmt, node))
            return
        if kind is AssignStmt:
            self._assign(cast(AssignStmt, node))
            return
        if kind is PrintStmt:
            self._print(cast(PrintStmt, node))
            return
        if kind is IfStmt:
            self._if(cast(IfStmt, node))
            return
        if kind is WhileStmt:
            self._while(cast(WhileStmt, node))
            return
        raise CompileError("invalid statement")

    def expression(self, node: object) -> None:
        if type(node) in _LITERALS:
            self.emit("CONST", self.pool(_literal_value(node)))
            return
        if type(node) is Ident:
            self._load(cast(Ident, node).name)
            return
        if type(node) is UnaryOp:
            self._unary(cast(UnaryOp, node))
            return
        if type(node) is BinaryOp:
            self._binary(cast(BinaryOp, node))
            return
        raise CompileError("invalid expression")

    def _block(self, node: Block) -> None:
        for stmt in node.statements:
            self.statement(stmt)

    def _let(self, node: LetStmt) -> None:
        self.expression(node.expr)
        self.emit("STORE", self._slot(node.name))

    def _assign(self, node: AssignStmt) -> None:
        self.expression(node.expr)
        self.emit("STORE", self._slot(node.name))

    def _print(self, node: PrintStmt) -> None:
        self.expression(node.expr)
        self.emit("PRINT")

    def _if(self, node: IfStmt) -> None:
        self.expression(node.cond)
        jump_false = self.emit("JUMP_IF_FALSE", 0)
        self.statement(node.then_body)
        if node.else_body is None:
            self.patch(jump_false, len(self.instructions))
            return
        jump_end = self.emit("JUMP", 0)
        self.patch(jump_false, len(self.instructions))
        self.statement(node.else_body)
        self.patch(jump_end, len(self.instructions))

    def _while(self, node: WhileStmt) -> None:
        start = len(self.instructions)
        self.expression(node.cond)
        jump_false = self.emit("JUMP_IF_FALSE", 0)
        self.statement(node.body)
        self.emit("JUMP", start)
        self.patch(jump_false, len(self.instructions))

    def _unary(self, node: UnaryOp) -> None:
        self.expression(node.operand)
        if node.op == "-":
            self.emit("NEG")
            return
        if node.op == "not":
            self.emit("NOT")
            return
        raise CompileError(f"unknown unary operator: {node.op}")

    def _binary(self, node: BinaryOp) -> None:
        if node.op == "and":
            self._and(node)
            return
        if node.op == "or":
            self._or(node)
            return
        self.expression(node.left)
        self.expression(node.right)
        opcode = _BIN_OPS.get(node.op)
        if opcode is None:
            raise CompileError(f"unknown operator: {node.op}")
        self.emit(opcode)

    def _and(self, node: BinaryOp) -> None:
        # NOT/NOT checks the evaluated right operand is BOOL; no check opcode exists.
        self.expression(node.left)
        jump_false = self.emit("JUMP_IF_FALSE", 0)
        self.expression(node.right)
        self.emit("NOT")
        self.emit("NOT")
        jump_end = self.emit("JUMP", 0)
        self.patch(jump_false, len(self.instructions))
        self.emit("CONST", self.pool(False))
        self.patch(jump_end, len(self.instructions))

    def _or(self, node: BinaryOp) -> None:
        self.expression(node.left)
        jump_false = self.emit("JUMP_IF_FALSE", 0)
        self.emit("CONST", self.pool(True))
        jump_end = self.emit("JUMP", 0)
        self.patch(jump_false, len(self.instructions))
        self.expression(node.right)
        self.emit("NOT")
        self.emit("NOT")
        self.patch(jump_end, len(self.instructions))

    def _load(self, name: str) -> None:
        self.emit("LOAD", self._slot(name))

    def _slot(self, name: str) -> int:
        slot = self._names.get(name)
        if slot is None:
            raise CompileError(f"undeclared variable: {name}")
        return slot


def _literal_value(node: object) -> object:
    if type(node) is IntLit:
        return cast(IntLit, node).value
    if type(node) is FloatLit:
        return cast(FloatLit, node).value
    if type(node) is StringLit:
        return cast(StringLit, node).value
    if type(node) is BoolLit:
        return cast(BoolLit, node).value
    raise CompileError("invalid literal")

from typing import cast

from microvm.errors import VMRuntimeError
from microvm.parser import (
    AssignStmt,
    BinaryOp,
    Block,
    BoolLit,
    FloatLit,
    IfStmt,
    IntLit,
    LetStmt,
    PrintStmt,
    ProgramNode,
    StringLit,
    UnaryOp,
    WhileStmt,
)

_NO_FOLD = object()


def fold_constants(node: object) -> object:
    kind = type(node)
    if kind is ProgramNode:
        root = cast(ProgramNode, node)
        return ProgramNode([fold_constants(stmt) for stmt in root.statements])
    if kind is Block:
        block = cast(Block, node)
        return Block([fold_constants(stmt) for stmt in block.statements], block.offset)
    if kind is LetStmt:
        stmt = cast(LetStmt, node)
        return LetStmt(stmt.name, fold_constants(stmt.expr), stmt.offset)
    if kind is AssignStmt:
        stmt = cast(AssignStmt, node)
        return AssignStmt(stmt.name, fold_constants(stmt.expr), stmt.offset)
    if kind is PrintStmt:
        stmt = cast(PrintStmt, node)
        return PrintStmt(fold_constants(stmt.expr), stmt.offset)
    if kind is IfStmt:
        return _fold_if(cast(IfStmt, node))
    if kind is WhileStmt:
        return _fold_while(cast(WhileStmt, node))
    if kind is BinaryOp:
        return _fold_binary(cast(BinaryOp, node))
    if kind is UnaryOp:
        return _fold_unary(cast(UnaryOp, node))
    return node


def _fold_if(stmt: IfStmt) -> IfStmt:
    else_body = None if stmt.else_body is None else fold_constants(stmt.else_body)
    cond = fold_constants(stmt.cond)
    then_body = fold_constants(stmt.then_body)
    return IfStmt(cond, then_body, else_body, stmt.offset)


def _fold_while(stmt: WhileStmt) -> WhileStmt:
    return WhileStmt(fold_constants(stmt.cond), fold_constants(stmt.body), stmt.offset)


def _fold_binary(expr: BinaryOp) -> object:
    left = fold_constants(expr.left)
    right = fold_constants(expr.right)
    if expr.op == "and":
        return _fold_and(left, right, expr.offset)
    if expr.op == "or":
        return _fold_or(left, right, expr.offset)
    return _fold_eager(expr.op, left, right, expr.offset)


def _fold_and(left: object, right: object, offset: int) -> object:
    if type(left) is BoolLit and type(right) is BoolLit:
        value = cast(BoolLit, left).value and cast(BoolLit, right).value
        return BoolLit(value, offset)
    # false and X never evaluates X, so dropping X cannot hide a bool check.
    if type(left) is BoolLit and cast(BoolLit, left).value is False:
        return BoolLit(False, offset)
    # true and X must stay: the runtime still checks that X is BOOL.
    return BinaryOp("and", left, right, offset)


def _fold_or(left: object, right: object, offset: int) -> object:
    if type(left) is BoolLit and type(right) is BoolLit:
        value = cast(BoolLit, left).value or cast(BoolLit, right).value
        return BoolLit(value, offset)
    if type(left) is BoolLit and cast(BoolLit, left).value is True:
        return BoolLit(True, offset)
    return BinaryOp("or", left, right, offset)


def _fold_eager(op: str, left: object, right: object, offset: int) -> object:
    if not _is_literal(left) or not _is_literal(right):
        return BinaryOp(op, left, right, offset)
    folded = _try_binary(op, _literal_value(left), _literal_value(right))
    if folded is _NO_FOLD:
        return BinaryOp(op, left, right, offset)
    made = _make_lit(folded, offset)
    if made is _NO_FOLD:
        return BinaryOp(op, left, right, offset)
    return made


def _fold_unary(expr: UnaryOp) -> object:
    operand = fold_constants(expr.operand)
    if not _is_literal(operand):
        return UnaryOp(expr.op, operand, expr.offset)
    folded = _try_unary(expr.op, _literal_value(operand))
    if folded is _NO_FOLD:
        return UnaryOp(expr.op, operand, expr.offset)
    made = _make_lit(folded, expr.offset)
    if made is _NO_FOLD:
        return UnaryOp(expr.op, operand, expr.offset)
    return made


def _try_binary(op: str, left: object, right: object) -> object:
    from microvm.vm import _apply_binary

    try:
        return _apply_binary(op, left, right)
    except VMRuntimeError:
        return _NO_FOLD


def _try_unary(op: str, value: object) -> object:
    from microvm.vm import _apply_unary

    try:
        return _apply_unary(op, value)
    except VMRuntimeError:
        return _NO_FOLD


def _is_literal(node: object) -> bool:
    return type(node) in (IntLit, FloatLit, StringLit, BoolLit)


def _literal_value(node: object) -> object:
    if type(node) is IntLit:
        return cast(IntLit, node).value
    if type(node) is FloatLit:
        return cast(FloatLit, node).value
    if type(node) is StringLit:
        return cast(StringLit, node).value
    return cast(BoolLit, node).value


def _make_lit(value: object, offset: int) -> object:
    if type(value) is bool:
        return BoolLit(value, offset)
    if type(value) is int:
        return IntLit(value, offset)
    if type(value) is float:
        return FloatLit(value, offset)
    if type(value) is str:
        return StringLit(value, offset)
    return _NO_FOLD

import dataclasses

from microvm.compiler import Instr, Program
from microvm.errors import StepLimitError, VMRuntimeError

_UNSET = object()
_BIN_OPS = {
    "ADD": "+",
    "SUB": "-",
    "MUL": "*",
    "DIV": "/",
    "MOD": "%",
    "EQ": "==",
    "NE": "!=",
    "LT": "<",
    "LE": "<=",
    "GT": ">",
    "GE": ">=",
}


@dataclasses.dataclass
class _State:
    program: Program
    stack: list[object]
    slots: list[object]
    output: list[str]
    ip: int
    steps: int


def execute(program: Program, *, step_limit: int = 100_000) -> list[str]:
    if type(step_limit) is not int or step_limit < 1:
        raise ValueError("step_limit must be a positive integer")
    state = _State(program, [], [_UNSET] * len(program.names), [], 0, 0)
    return _loop(state, step_limit)


def _loop(state: _State, step_limit: int) -> list[str]:
    code = state.program.instructions
    while True:
        if state.steps >= step_limit:
            raise StepLimitError("step limit exceeded")
        if state.ip < 0 or state.ip >= len(code):
            raise VMRuntimeError("invalid instruction pointer")
        instr = code[state.ip]
        state.steps += 1
        if instr.op == "HALT":
            return state.output
        if not _exec(state, instr):
            state.ip += 1


def _exec(state: _State, instr: Instr) -> bool:
    handler = _HANDLERS.get(instr.op)
    if handler is None:
        raise VMRuntimeError(f"unknown opcode: {instr.op}")
    return handler(state, instr)


def _apply_binary(op: str, left: object, right: object) -> object:
    if op in ("+", "-", "*"):
        return _arith(op, left, right)
    if op == "/":
        return _div(left, right)
    if op == "%":
        return _mod(left, right)
    if op in ("==", "!="):
        same = _equal(left, right)
        return same if op == "==" else not same
    if op in ("<", "<=", ">", ">="):
        return _ordered(op, left, right)
    raise VMRuntimeError(f"unknown operator: {op}")


def _apply_unary(op: str, value: object) -> object:
    if op == "-":
        return _neg(value)
    if op == "not":
        return _not(value)
    raise VMRuntimeError(f"unknown unary operator: {op}")


def _is_int(value: object) -> bool:
    return type(value) is int


def _is_float(value: object) -> bool:
    return type(value) is float


def _is_number(value: object) -> bool:
    return type(value) is int or type(value) is float


def _is_bool(value: object) -> bool:
    return type(value) is bool


def _is_str(value: object) -> bool:
    return type(value) is str


def _arith(op: str, left: object, right: object) -> object:
    if op == "+" and _is_str(left) and _is_str(right):
        return left + right
    if not _is_number(left) or not _is_number(right):
        raise VMRuntimeError(f"invalid operands for {op}")
    result = _raw_arith(op, left, right)
    if _is_int(left) and _is_int(right):
        return int(result)
    return float(result)


def _raw_arith(op: str, left: object, right: object) -> object:
    if op == "+":
        return left + right  # type: ignore[operator]
    if op == "-":
        return left - right  # type: ignore[operator]
    return left * right  # type: ignore[operator]


def _div(left: object, right: object) -> float:
    if not _is_number(left) or not _is_number(right):
        raise VMRuntimeError("invalid operands for /")
    if right == 0:
        raise VMRuntimeError("division by zero")
    return float(left) / float(right)  # type: ignore[arg-type]


def _mod(left: object, right: object) -> int:
    if not _is_int(left) or not _is_int(right):
        raise VMRuntimeError("invalid operands for %")
    if right == 0:
        raise VMRuntimeError("modulo by zero")
    return left % right  # type: ignore[operator]


def _equal(left: object, right: object) -> bool:
    if _is_bool(left) or _is_bool(right):
        return _is_bool(left) and _is_bool(right) and left == right
    if _is_number(left) and _is_number(right):
        return left == right
    if type(left) is type(right):
        return left == right
    return False


def _ordered(op: str, left: object, right: object) -> bool:
    numeric = _is_number(left) and _is_number(right)
    textual = _is_str(left) and _is_str(right)
    if not numeric and not textual:
        raise VMRuntimeError(f"invalid operands for {op}")
    return _cmp(op, left, right)


def _cmp(op: str, left: object, right: object) -> bool:
    if op == "<":
        return left < right  # type: ignore[operator]
    if op == "<=":
        return left <= right  # type: ignore[operator]
    if op == ">":
        return left > right  # type: ignore[operator]
    return left >= right  # type: ignore[operator]


def _neg(value: object) -> object:
    if _is_int(value) or _is_float(value):
        return -value  # type: ignore[operator]
    raise VMRuntimeError("unary minus requires a number")


def _not(value: object) -> object:
    if not _is_bool(value):
        raise VMRuntimeError("not requires a bool")
    return not value


def _render(value: object) -> str:
    if _is_bool(value):
        return "true" if value else "false"
    if _is_int(value) or _is_float(value) or _is_str(value):
        return str(value)
    raise VMRuntimeError("cannot print value")


def _pop(state: _State) -> object:
    if not state.stack:
        raise VMRuntimeError("stack underflow")
    return state.stack.pop()


def _arg(instr: Instr) -> int:
    if type(instr.arg) is not int:
        raise VMRuntimeError(f"{instr.op} missing argument")
    return instr.arg


def _check_slot(state: _State, index: int) -> None:
    if index < 0 or index >= len(state.slots):
        raise VMRuntimeError("variable index out of range")


def _op_const(state: _State, instr: Instr) -> bool:
    index = _arg(instr)
    if index < 0 or index >= len(state.program.constants):
        raise VMRuntimeError("constant index out of range")
    state.stack.append(state.program.constants[index])
    return False


def _op_load(state: _State, instr: Instr) -> bool:
    index = _arg(instr)
    _check_slot(state, index)
    value = state.slots[index]
    if value is _UNSET:
        name = state.program.names[index]
        raise VMRuntimeError(f"variable '{name}' is uninitialized")
    state.stack.append(value)
    return False


def _op_store(state: _State, instr: Instr) -> bool:
    index = _arg(instr)
    _check_slot(state, index)
    state.slots[index] = _pop(state)
    return False


def _op_binary(state: _State, instr: Instr) -> bool:
    right = _pop(state)
    left = _pop(state)
    state.stack.append(_apply_binary(_BIN_OPS[instr.op], left, right))
    return False


def _op_unary(state: _State, instr: Instr) -> bool:
    op = "-" if instr.op == "NEG" else "not"
    state.stack.append(_apply_unary(op, _pop(state)))
    return False


def _op_jump(state: _State, instr: Instr) -> bool:
    state.ip = _arg(instr)
    return True


def _op_jump_if_false(state: _State, instr: Instr) -> bool:
    cond = _pop(state)
    if type(cond) is not bool:
        raise VMRuntimeError("condition must be bool")
    if not cond:
        state.ip = _arg(instr)
        return True
    return False


def _op_print(state: _State, instr: Instr) -> bool:
    state.output.append(_render(_pop(state)))
    return False


def _op_pop(state: _State, instr: Instr) -> bool:
    _pop(state)
    return False


_HANDLERS = {
    "CONST": _op_const,
    "LOAD": _op_load,
    "STORE": _op_store,
    "ADD": _op_binary,
    "SUB": _op_binary,
    "MUL": _op_binary,
    "DIV": _op_binary,
    "MOD": _op_binary,
    "NEG": _op_unary,
    "NOT": _op_unary,
    "EQ": _op_binary,
    "NE": _op_binary,
    "LT": _op_binary,
    "LE": _op_binary,
    "GT": _op_binary,
    "GE": _op_binary,
    "JUMP": _op_jump,
    "JUMP_IF_FALSE": _op_jump_if_false,
    "PRINT": _op_print,
    "POP": _op_pop,
}

import struct
import zlib

from microvm.compiler import Instr, Program
from microvm.errors import SerializationError
from microvm.opcodes import OPCODE_NUMBERS

_ARG_OPS = frozenset({"CONST", "LOAD", "STORE", "JUMP", "JUMP_IF_FALSE"})
_NO_ARG = 0xFFFFFFFF
_INT_MIN = -9223372036854775808
_INT_MAX = 9223372036854775807
_OP_BY_NUMBER = {number: name for name, number in OPCODE_NUMBERS.items()}


def dumps(program: Program) -> bytes:
    body = bytearray()
    body.append(1)
    _write_names(body, program.names)
    _write_constants(body, program.constants)
    _write_instructions(body, program.instructions)
    checksum = zlib.crc32(body) & 0xFFFFFFFF
    return b"MVM1" + bytes(body) + checksum.to_bytes(4, "big")


def loads(data: bytes) -> Program:
    raw = _as_bytes(data)
    if len(raw) < 4:
        raise SerializationError("truncated input")
    if raw[:4] != b"MVM1":
        raise SerializationError("bad magic")
    if len(raw) < 8:
        raise SerializationError("truncated input")
    # Checksum is the last 4 bytes and is verified before any length field is read.
    body = raw[4:-4]
    checksum = int.from_bytes(raw[-4:], "big")
    if (zlib.crc32(body) & 0xFFFFFFFF) != checksum:
        raise SerializationError("checksum mismatch")
    return _parse_body(body)


def _as_bytes(data: bytes) -> bytes:
    if type(data) is bytes:
        return data
    if type(data) is bytearray or type(data) is memoryview:
        return bytes(data)
    raise SerializationError("data must be bytes")


def _write_names(body: bytearray, names: list[str]) -> None:
    if len(names) > 65535:
        raise SerializationError("too many names")
    body += len(names).to_bytes(2, "big")
    for name in names:
        raw = name.encode("utf-8")
        if len(raw) > 65535:
            raise SerializationError("name too long")
        body += len(raw).to_bytes(2, "big")
        body += raw


def _write_constants(body: bytearray, constants: list[object]) -> None:
    if len(constants) > 65535:
        raise SerializationError("too many constants")
    body += len(constants).to_bytes(2, "big")
    for value in constants:
        _write_constant(body, value)


def _write_constant(body: bytearray, value: object) -> None:
    if type(value) is bool:
        body.append(0x04)
        body.append(1 if value else 0)
        return
    if type(value) is int:
        _write_int(body, value)
        return
    if type(value) is float:
        body.append(0x02)
        body += struct.pack(">d", value)
        return
    if type(value) is str:
        _write_string(body, value)
        return
    raise SerializationError("unsupported constant type")


def _write_int(body: bytearray, value: int) -> None:
    if value < _INT_MIN or value > _INT_MAX:
        raise SerializationError("integer out of range")
    body.append(0x01)
    body += value.to_bytes(8, "big", signed=True)


def _write_string(body: bytearray, value: str) -> None:
    raw = value.encode("utf-8")
    if len(raw) > 0xFFFFFFFF:
        raise SerializationError("string too long")
    body.append(0x03)
    body += len(raw).to_bytes(4, "big")
    body += raw


def _write_instructions(body: bytearray, instructions: list[Instr]) -> None:
    if len(instructions) > 0xFFFFFFFF:
        raise SerializationError("too many instructions")
    body += len(instructions).to_bytes(4, "big")
    for instr in instructions:
        _write_instr(body, instr)


def _write_instr(body: bytearray, instr: Instr) -> None:
    number = OPCODE_NUMBERS.get(instr.op)
    if number is None:
        raise SerializationError(f"unknown opcode: {instr.op}")
    body.append(number)
    if instr.op in _ARG_OPS:
        if type(instr.arg) is not int or not 0 <= instr.arg <= 0xFFFFFFFE:
            raise SerializationError("invalid instruction argument")
        body += instr.arg.to_bytes(4, "big")
        return
    if instr.arg is not None:
        raise SerializationError("unexpected instruction argument")
    body += b"\xff\xff\xff\xff"


def _parse_body(body: bytes) -> Program:
    reader = _Reader(body)
    version = reader.u8()
    if version != 1:
        raise SerializationError("unsupported version")
    names = _read_names(reader)
    constants = _read_constants(reader)
    instructions = _read_instructions(reader)
    if not reader.done():
        raise SerializationError("trailing bytes")
    return Program(constants, names, instructions)


def _read_names(reader: "_Reader") -> list[str]:
    count = reader.u16()
    return [_read_utf8(reader, reader.u16(), "name") for _ in range(count)]


def _read_constants(reader: "_Reader") -> list[object]:
    count = reader.u16()
    return [_read_constant(reader) for _ in range(count)]


def _read_constant(reader: "_Reader") -> object:
    tag = reader.u8()
    if tag == 0x01:
        return reader.i64()
    if tag == 0x02:
        return reader.f64()
    if tag == 0x03:
        return _read_utf8(reader, reader.u32(), "string")
    if tag == 0x04:
        return _read_bool(reader)
    raise SerializationError("unknown constant tag")


def _read_bool(reader: "_Reader") -> bool:
    flag = reader.u8()
    if flag not in (0, 1):
        raise SerializationError("invalid bool")
    return flag == 1


def _read_utf8(reader: "_Reader", length: int, label: str) -> str:
    try:
        return reader.take(length).decode("utf-8")
    except UnicodeDecodeError as exc:
        raise SerializationError(f"invalid utf-8 {label}") from exc


def _read_instructions(reader: "_Reader") -> list[Instr]:
    count = reader.u32()
    return [_read_instr(reader) for _ in range(count)]


def _read_instr(reader: "_Reader") -> Instr:
    op = _OP_BY_NUMBER.get(reader.u8())
    arg_raw = reader.u32()
    if op is None:
        raise SerializationError("unknown opcode")
    if op in _ARG_OPS:
        if arg_raw == _NO_ARG:
            raise SerializationError("missing instruction argument")
        return Instr(op, arg_raw)
    if arg_raw != _NO_ARG:
        raise SerializationError("unexpected instruction argument")
    return Instr(op, None)


class _Reader:
    def __init__(self, data: bytes) -> None:
        self.data = data
        self.pos = 0

    def done(self) -> bool:
        return self.pos == len(self.data)

    def take(self, size: int) -> bytes:
        end = self.pos + size
        if size < 0 or end > len(self.data):
            raise SerializationError("truncated input")
        chunk = self.data[self.pos:end]
        self.pos = end
        return chunk

    def u8(self) -> int:
        return self.take(1)[0]

    def u16(self) -> int:
        return int.from_bytes(self.take(2), "big")

    def u32(self) -> int:
        return int.from_bytes(self.take(4), "big")

    def i64(self) -> int:
        return int.from_bytes(self.take(8), "big", signed=True)

    def f64(self) -> float:
        return struct.unpack(">d", self.take(8))[0]

import argparse
import sys
from typing import Sequence

from microvm.compiler import compile_source
from microvm.disassembler import disassemble
from microvm.errors import MicroVMError
from microvm.serializer import dumps, loads
from microvm.vm import execute


class _UsageError(Exception):
    def __init__(self, message: str) -> None:
        super().__init__(message)


def main(argv: list[str] | None = None) -> int:
    parser = _build_parser()
    try:
        args = parser.parse_args(argv)
    except SystemExit as exc:
        code = exc.code
        return code if type(code) is int else 2
    try:
        _run_command(args)
    except _UsageError as exc:
        print(exc, file=sys.stderr)
        return 2
    except MicroVMError as exc:
        print(exc, file=sys.stderr)
        return 3
    return 0


def _build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(prog="microvm")
    sub = parser.add_subparsers(dest="command", required=True)
    _add_run(sub)
    _add_build(sub)
    _add_exec(sub)
    _add_disasm(sub)
    return parser


def _add_run(sub: argparse._SubParsersAction) -> None:  # type: ignore[type-arg]
    cmd = sub.add_parser("run")
    cmd.add_argument("file")
    cmd.add_argument("--optimize", action="store_true")
    cmd.add_argument("--step-limit", type=_positive_int, default=100_000)


def _add_build(sub: argparse._SubParsersAction) -> None:  # type: ignore[type-arg]
    cmd = sub.add_parser("build")
    cmd.add_argument("file")
    cmd.add_argument("out")
    cmd.add_argument("--optimize", action="store_true")


def _add_exec(sub: argparse._SubParsersAction) -> None:  # type: ignore[type-arg]
    cmd = sub.add_parser("exec")
    cmd.add_argument("file")
    cmd.add_argument("--step-limit", type=_positive_int, default=100_000)


def _add_disasm(sub: argparse._SubParsersAction) -> None:  # type: ignore[type-arg]
    cmd = sub.add_parser("disasm")
    cmd.add_argument("file")


def _positive_int(text: str) -> int:
    try:
        value = int(text, 10)
    except ValueError as exc:
        raise argparse.ArgumentTypeError("step-limit must be a positive integer") from exc
    if value < 1:
        raise argparse.ArgumentTypeError("step-limit must be a positive integer")
    return value


def _run_command(args: argparse.Namespace) -> None:
    if args.command == "run":
        _cmd_run(args)
        return
    if args.command == "build":
        _cmd_build(args)
        return
    if args.command == "exec":
        _cmd_exec(args)
        return
    if args.command == "disasm":
        _cmd_disasm(args)
        return
    raise _UsageError(f"unknown command: {args.command}")


def _cmd_run(args: argparse.Namespace) -> None:
    program = compile_source(_read_text(args.file), optimize=args.optimize)
    _write_lines(execute(program, step_limit=args.step_limit))


def _cmd_build(args: argparse.Namespace) -> None:
